  \def\r{3}
    \path
    (0,0) coordinate (B)
    ++(0:2*\r) coordinate (C)
    ($(B)!0.5!(C)$) coordinate (O)
    (O)++(120:\r) coordinate (A)
 ($(B)!1!-90:(A)$) coordinate (Bx) 
 (B)++(90:2cm) coordinate (By) ;
 \path[name path = dtron1] let \p1=($(A) - (B)$) in (A) circle ({veclen(\x1,\y1)}); 
 \path[name path=dthang] (A)--(C); 
 \path[name path=dtron] let \p1=($ (A) - (B) $) in (A) circle ({veclen(\x1,\y1)}); 
 \path[name intersections={of=dtron and dthang, by={D}}];
  \path ($(D)!1!90:(A)$) coordinate (Dx) (intersection of B--Bx and D--Dx) coordinate (E) ($(E)!(O)!(A)$) coordinate (E1) ($(A)!2!(E1)$) coordinate (F) (intersection of C--F and E--D) coordinate (I) ; 
 \draw (A)--(B)--(C)--cycle (B)--(E)--(D)(B)--(I)--(E)(B)--(F)--(I)--cycle (D)--(F)--(C)(A)--(F)(B)--(By); 
 \draw let \p2=($(O) - (A)$) in (O) circle ({veclen(\x2,\y2)}); 

    \filldraw[black] (A) circle (1pt) node[above] {$B$};
    \filldraw[black] (B) circle (1pt) node[left] {$C$};
    \filldraw[black] (C) circle (1pt) node[above right] {$H$};
   \filldraw[black] (D) circle (1pt) node[above right]{$I$};
    \filldraw[black] (E) circle (1pt) node[below left] {$J$};
    \filldraw[black] (F) circle (1pt) node[below] {$K$};
     \filldraw[black] (I) circle (1pt) node[below] {$N$};
    \filldraw[black] (O) circle (1pt) node[below ] {$O$};
